import {profile,chooseProfile,logOut} from './profile.js';
import * as T from './vendor/three.js';
import {gameState,missions,costs,startMission,inspectCitizen,build,undoBuild,remaining,goals,challengeStep,freePlay} from './challenges.js';
import {Simulation,factions} from './sim.js';
import {neuralView,ensureBrain,infer} from './brain.js';
import {portrait} from './avatars.js';
import {createWorld} from './world.js';
import {loadWorld,saveWorld,download} from './vault.js';
import {WIDTH,DEPTH,districts,typeNames,typeColors,nearestParcel,road,clamp} from './city.js';
const $=id=>document.getElementById(id),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const demo=new URLSearchParams(location.search).get('demo')==='1';
const initial=await chooseProfile(()=>loadWorld(),async name=>{const saved=await loadWorld(name?'profile:'+name:'active')||await loadWorld();if(!saved)throw Error('No browser backup found.');download('free-city-browser-backup.json',saved)});
let sim=new Simulation(initial),speed=1,selected=sim.citizens[0]?.id??0,view='activity',drawer='',tool='',following=false,auto=false,angle=.65,elevation=.85,distance=180,target=new T.Vector3(-20,0,0),keys=new Set(),saveStatus='Saving…',saving=false,leaving=false;
gameState(sim);
const world=createWorld($('world'),sim);world.update(sim,selected,1,0);
function toast(s){$('toast').textContent=s;$('toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').style.display='none',4000)}
async function save(){if(leaving)return true;if(demo){saveStatus='Demo world · saves disabled';$('saveStatus').textContent=saveStatus;return}if(saving)return false;saving=true;try{await saveWorld(sim);saveStatus=profile?'Cloud saved · '+profile:'Saved in this browser';$('saveStatus').textContent=saveStatus;return true}catch(e){saveStatus=e.status===409?'Save conflict · reload required':'Cloud save failed · export a backup';$('saveStatus').textContent=saveStatus;if(e.status===409)setSpeed(0);toast(e.message||'Save failed. Export your world to keep it.');return false}finally{saving=false}}
await save();setInterval(save,30000);addEventListener('visibilitychange',()=>{if(document.hidden)save()});addEventListener('pagehide',()=>save());
function person(){return [...sim.citizens,...sim.archived].find(c=>c.id===selected)}
function select(id){selected=id;inspectCitizen(sim,id);view='activity';following=false;$('inspector').classList.remove('hidden');$('drawer').classList.add('hidden');drawer='';setTool('');update();}
function setTool(t){tool=t;$('buildBanner').classList.toggle('hidden',!t);$('toolName').textContent=t?`PLACE ${typeNames[t]||t.replace('-',' ').toUpperCase()} · click a lot or street`:'';world.ghost.visible=!!t;if($('placeCenter'))$('placeCenter').disabled=!t;document.querySelectorAll('[data-tool]').forEach(b=>b.classList.toggle('active',b.dataset.tool===t))}
function pan(dx,dy){const scale=distance*.0012;target.x=clamp(target.x+(-dx*Math.cos(angle)-dy*Math.sin(angle))*scale,-90,90);target.z=clamp(target.z+(dx*Math.sin(angle)-dy*Math.cos(angle))*scale,-68,68);following=false}
let down;world.renderer.domElement.style.touchAction='none';world.renderer.domElement.addEventListener('pointerdown',e=>{down={x:e.clientX,y:e.clientY,sx:e.clientX,sy:e.clientY,button:e.button,moved:false};world.renderer.domElement.setPointerCapture(e.pointerId)});
world.renderer.domElement.addEventListener('pointermove',e=>{if(tool){const p=world.ground(e);if(p){const lot=nearestParcel(sim.world,p.x,p.z);world.ghost.position.set(tool.includes('road')?road(p.x,80):tool==='hazard'?p.x:lot.x,.35,tool.includes('road')?road(p.z,60):tool==='hazard'?p.z:lot.z)}}if(!down)return;const dx=e.clientX-down.x,dy=e.clientY-down.y;if(Math.hypot(e.clientX-down.sx,e.clientY-down.sy)>5)down.moved=true;if(down.button===2){angle-=dx*.006;elevation=clamp(elevation+dy*.004,.4,1.4)}else pan(dx,dy);down.x=e.clientX;down.y=e.clientY});
world.renderer.domElement.addEventListener('pointerup',e=>{if(down&&!down.moved&&down.button===0){if(tool){const p=world.ground(e);if(p&&Math.abs(p.x)<86&&Math.abs(p.z)<65){const result=build(sim,tool,p.x,p.z);save();update();toast(result.message)}else toast('Choose a lot or street inside the city.')}else{const id=world.pick(e);if(id!==undefined)select(id)}}down=null});world.renderer.domElement.addEventListener('pointercancel',()=>down=null);world.renderer.domElement.addEventListener('contextmenu',e=>e.preventDefault());world.renderer.domElement.addEventListener('wheel',e=>{e.preventDefault();distance=clamp(distance+e.deltaY*.07,25,320)},{passive:false});addEventListener('resize',world.resize);
addEventListener('keydown',e=>{if(['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName)||$('guide').open||$('lobby').open)return;if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight',' '].includes(e.key))e.preventDefault();keys.add(e.key.toLowerCase());if(e.key==='Escape')setTool('');if(e.key===' '&&!e.repeat)setSpeed(speed?0:1)});addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));addEventListener('blur',()=>keys.clear());
function setSpeed(v){speed=v;document.querySelectorAll('[data-speed]').forEach(b=>b.classList.toggle('active',+b.dataset.speed===v))}document.querySelectorAll('[data-speed]').forEach(b=>b.onclick=()=>setSpeed(+b.dataset.speed));
$('zoomIn').onclick=()=>distance=Math.max(25,distance-15);$('zoomOut').onclick=()=>distance=Math.min(320,distance+15);$('turnLeft').onclick=()=>angle-=Math.PI/4;$('turnRight').onclick=()=>angle+=Math.PI/4;document.querySelectorAll('[data-pan]').forEach(b=>b.onclick=()=>{const [x,y]=b.dataset.pan.split(',').map(Number);pan(x*95,y*95)});
$('home').onclick=()=>{following=false;target.set(-20,0,0);distance=180;angle=.65;elevation=.85};$('orbit').onclick=()=>{auto=!auto;$('orbit').classList.toggle('active',auto)};$('close').onclick=()=>$('inspector').classList.add('hidden');$('cancelTool').onclick=()=>setTool('');$('minimap').onclick=e=>{const r=e.currentTarget.getBoundingClientRect();target.set((e.clientX-r.left)/r.width*WIDTH-WIDTH/2,0,(e.clientY-r.top)/r.height*DEPTH-DEPTH/2);following=false;distance=Math.min(distance,105)};
function drawMap(){const g=$('minimap').getContext('2d'),sx=192/WIDTH,sz=144/DEPTH;g.fillStyle='#aad18b';g.fillRect(0,0,192,144);g.fillStyle='#60bdd4';g.fillRect(184,0,8,144);g.fillStyle='#ebd8a8';for(let x=-80;x<=80;x+=20)g.fillRect((x+96)*sx-2,8,4,128);for(let z=-60;z<=60;z+=20)g.fillRect(12,(z+72)*sz-2,168,4);for(const p of sim.world.parcels){g.fillStyle=typeColors[p.type];g.fillRect((p.x+96)*sx-5,(p.z+72)*sz-5,10,10)}for(const c of sim.citizens){g.fillStyle=c.id===selected?'#fff':factions[c.faction]==='Commons'?'#2d8c73':'#3c4475';g.fillRect((c.x+96)*sx-1,(c.z+72)*sz-1,3,3)}for(const k of sim.world.closed){const [x,z]=k.split(',').map(Number);g.fillStyle='#d84959';g.fillRect(x+94,z+70,4,4)}g.strokeStyle='#243b63';g.lineWidth=2;g.strokeRect(target.x+96-distance*.16,target.z+72-distance*.1,distance*.32,distance*.2)}
function activity(c){const p=sim.world.parcels.find(p=>p.id===c.task?.placeId),home=sim.world.parcels.find(p=>p.id===c.home);return `<div class="goal-card"><b>${esc(c.phase.toUpperCase())} · ${esc(c.action)}</b><p>${esc(c.thought)}</p></div><div class="trip"><span>DESTINATION</span><b>${esc(p?.name||'Choosing the next activity')}</b><small>${c.route.length?`${c.route.length} route waypoints · following city streets`:c.task?`${Math.max(0,c.task.remaining)} activity ticks remaining`:'Considering needs, memories, and surroundings'}</small></div><div class="section-title">PERSONAL GOAL</div><p class="mem">${esc(c.goal)}</p><div class="section-title">NEEDS & PERSONALITY <span>¤${Math.floor(c.wealth)}</span></div>${['hunger','energy','social','health','curiosity','empathy','ambition','caution'].map(k=>`<div class="barrow"><span>${k==='hunger'?'Nourishment':k[0].toUpperCase()+k.slice(1)}</span><span>${Math.round(c[k])}%</span></div><div class="bar"><i style="width:${c[k]}%"></i></div>`).join('')}<div class="divider"></div><div class="section-title">HOUSEHOLD</div><p class="mem">${esc(home?.name||'Unassigned')}<br>${esc(c.partner!==null?sim.citizens.find(p=>p.id===c.partner)?.name||'Partner deceased':'No partner')} · ${c.children} children</p>`}
function memories(c){const b=ensureBrain(c);return `<div class="vault-summary"><b>${b.updates}</b> learned experiences <b>${b.lessons.length}</b> consolidated lessons</div><h3>EPISODIC MEMORY</h3>${b.episodes.length?b.episodes.slice(0,18).map(e=>`<div class="episode"><span>DAY ${e.day} · ${esc(e.action)}</span><b>${esc(e.place)}</b><p>${esc(e.outcome)}</p><small class="${e.reward<0?'negative':''}">Reward ${e.reward.toFixed(3)} · prediction error ${e.error.toFixed(3)}</small></div>`).join(''):'<p class="mem">Experiences appear after an activity finishes. Traveling alone does not award food or wages.</p>'}<h3>LONG-TERM LESSONS</h3>${b.lessons.map(l=>`<p class="mem">Day ${l.day} · ${esc(l.text)}</p>`).join('')||'<p class="mem">Repeated experience consolidates a lesson every eight outcomes.</p>'}<h3>LIFE EVENTS</h3>${c.memories.map(m=>`<p class="mem">${esc(m)}</p>`).join('')}`}
function folder(c){const b=ensureBrain(c);return `<div class="folder-path">▣ citizens / ${String(c.id).padStart(4,'0')} / mind</div><p class="mem">Personal records are included in your username’s cloud save, with a backup in this browser. Export to keep an independent file on your computer.</p><div class="folder-file"><b>neural-weights.json</b><span>1,024 plastic + 1,024 consolidated weights</span></div><div class="folder-file"><b>working-memory.json</b><span>16 recurrent context values</span></div><div class="folder-file"><b>experiences.json</b><span>${b.episodes.length} recent episodes · latest 100 retained</span></div><div class="folder-file"><b>learned-places.json</b><span>${Object.keys(b.places).length} places with reward associations</span></div><div class="folder-file"><b>long-term-lessons.json</b><span>${b.lessons.length} consolidated lessons · latest 24 retained</span></div>${b.legacy?`<div class="folder-file"><b>legacy-brain.json</b><span>Preserved ${b.legacy.updates} updates from the previous model</span></div>`:''}<button id="exportMind" class="wide">↓ Export this citizen’s mind</button><p class="mem">${esc(saveStatus)}. The export bundles these records into one JSON file.</p><h3>LEARNED PLACES</h3>${Object.values(b.places).sort((a,b)=>b.value-a.value).slice(0,10).map(p=>`<p class="mem">${esc(p.name)} · ${p.visits} visits · value ${p.value.toFixed(2)}</p>`).join('')||'<p class="mem">No completed visits yet.</p>'}`}
function renderCitizen(){const c=person();if(!c){$('detail').innerHTML='<p>Select a citizen from the directory.</p>';return}ensureBrain(c);if(!c.brain.trace&&!c.died)infer(c,sim);const scroll=$('inspector').scrollTop;$('detail').innerHTML=`<div class="citizen-card"><img src="${portrait(c.id)}" alt="${esc(c.name)} avatar"><div><span class="dex-number">CITIZEN #${String(c.id+1).padStart(3,'0')}</span><h2>${esc(c.name)}</h2><div class="sub">${esc(c.job)} · Age ${Math.floor(c.age)} · ${factions[c.faction]}</div></div></div><div class="citizen-actions"><span class="mood">${c.died?'Archived mind':`${esc(c.phase)} · ${esc(c.action)}`}</span>${!c.died?`<button id="followCitizen">${following?'■ Unfollow':'◎ Follow'}</button>`:''}</div><div class="journal-tabs">${['activity','brain','memories','folder'].map(v=>`<button data-view="${v}" class="${view===v?'active':''}">${v==='folder'?'Mind folder':v[0].toUpperCase()+v.slice(1)}</button>`).join('')}</div><div class="journal-body">${view==='brain'?'<div class="network">'+neuralView(c)+'</div>':view==='memories'?memories(c):view==='folder'?folder(c):activity(c)}</div>`;document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;renderCitizen()});if($('followCitizen'))$('followCitizen').onclick=()=>{following=!following;if(following){target.set(c.x,0,c.z);distance=58}renderCitizen()};if($('exportMind'))$('exportMind').onclick=()=>download(`citizen-${c.id}-mind.json`,{path:`citizens/${String(c.id).padStart(4,'0')}/mind`,name:c.name,brain:c.brain,memories:c.memories,parents:c.parents,exportedAt:new Date().toISOString()});$('inspector').scrollTop=scroll}
function update(){const citizens=sim.citizens;$('clock').textContent=`DAY ${Math.floor(sim.day)} · ${String(Math.floor(sim.day%1*24)).padStart(2,'0')}:00`;$('population').textContent=citizens.length;$('happiness').textContent=`${Math.round(citizens.reduce((s,c)=>s+(c.hunger+c.energy+c.social)/3,0)/Math.max(1,citizens.length))}%`;$('treasury').textContent=Math.round(sim.treasury).toLocaleString();$('peace').textContent=sim.tension>65?'Conflict':sim.tension>40?'Tense':'Peace';$('weatherLabel').textContent=sim.weather;$('tax').textContent=`${Math.round(sim.tax*100)}% TAX`;$('government').textContent=`${citizens.find(c=>c.id===sim.leader)?.name||'Council'} · Food ${Math.floor(sim.food)} · Power ${sim.power}%`;$('events').innerHTML=sim.events.slice(0,4).map(e=>`<div class="event"><time>DAY ${e.day}</time>${esc(e.text)}</div>`).join('');$('saveStatus').textContent=saveStatus;if(!$('inspector').classList.contains('hidden'))renderCitizen();drawMap();updateGameHUD()}
function openDrawer(kind){setTool('');drawer=kind;$('drawer').classList.remove('hidden');$('inspector').classList.add('hidden')}
function showPeople(){if(drawer==='people'){$('drawer').classList.add('hidden');drawer='';return}openDrawer('people');$('drawer').innerHTML=`<div class="section-title">CITIZEN DIRECTORY <button id="drawerClose">×</button></div><input id="search" placeholder="Find a citizen or profession…" aria-label="Find a citizen"><label class="archive-toggle"><input type="checkbox" id="showArchived"> Include archived minds</label><div id="list"></div>`;$('search').oninput=filter;$('showArchived').onchange=filter;$('drawerClose').onclick=closeDrawer;filter()}
function closeDrawer(){$('drawer').classList.add('hidden');drawer='';setTool('')}
function filter(){const q=$('search').value.toLowerCase();$('list').innerHTML='';for(const c of [...sim.citizens,...($('showArchived').checked?sim.archived:[])].filter(c=>(c.name+' '+c.job).toLowerCase().includes(q))){const b=document.createElement('button');b.className='person';b.innerHTML=`<img src="${portrait(c.id)}" alt=""><span>${esc(c.name)}<small>${c.died?'Archived':esc(c.job)+' · '+esc(c.phase)}</small></span>`;b.onclick=()=>{select(c.id);if(!c.died){target.set(c.x,0,c.z);distance=65}};$('list').append(b)}}
function sandbox(){if(drawer==='sandbox'){closeDrawer();return}openDrawer('sandbox');$('drawer').innerHTML=`<div class="section-title">ENVIRONMENT SANDBOX <button id="drawerClose">×</button></div><p class="mem">Shape the city. Citizens choose their own lives. Select a tool, then click a lot; changes replace that lot. Undo restores the last edit.</p>${gameState(sim).run?.status==='active'?'<p class="challenge-budget">Challenge grant: <b id="grantBudget">'+remaining(sim)+'</b> coins remaining. Prices are shown below.</p>':''}<h3>BUILD & LANDSCAPE</h3><div class="tool-grid">${Object.entries(typeNames).filter(([k])=>k!=='empty').map(([k,v])=>`<button data-tool="${k}">${v}${gameState(sim).run?.status==='active'?'<small>'+(costs[k]||0)+' coins</small>':''}</button>`).join('')}<button data-tool="empty">Clear lot${gameState(sim).run?.status==='active'?' · 10 coins':''}</button><button data-tool="restore">Restore lot</button></div><button id="placeCenter" class="wide" disabled>Place selected tool at view center</button><h3>ROUTES & EVENTS</h3><div class="tool-grid"><button data-tool="close-road">Close junction${gameState(sim).run?.status==='active'?' · 20 coins':''}</button><button data-tool="open-road">Open junction${gameState(sim).run?.status==='active'?' · 10 coins':''}</button><button data-tool="hazard">Local hazard</button><button id="undo">↶ Undo edit</button></div><h3>WEATHER</h3><div class="tool-grid">${['Clear','Rain','Storm','Heatwave'].map(w=>`<button data-weather="${w}" class="${sim.weather===w?'active':''}">${w}</button>`).join('')}</div><label class="setting">Daylight<select id="light">${['Cycle','Day','Night'].map(v=>`<option ${sim.light===v?'selected':''}>${v}</option>`).join('')}</select></label>${[['fertility','Soil fertility',0,200],['power','City power',0,100],['temperature','Temperature °C',0,45]].map(([key,label,min,max])=>`<label class="setting">${label}<output id="${key}Value">${sim[key]}</output><input id="${key}" type="range" min="${min}" max="${max}" value="${sim[key]}" aria-label="${label}"></label>`).join('')}<div class="tool-grid"><button data-event="Abundance">Food shipment +250</button><button data-event="Scarcity">Crop failure −80%</button><button data-event="Discovery">Research discovery</button><button id="exportWorld">↓ Export world</button></div><p class="brain-note">Hazards last one city day. Weather lasts three. Power changes wages, rest, and healthcare. Fertility changes harvests. Closed junctions trigger new routes. Controls never assign a citizen an action.</p>`;$('drawerClose').onclick=closeDrawer;$('placeCenter').onclick=()=>{if(tool){const result=build(sim,tool,target.x,target.z);save();update();toast(result.message)}};document.querySelectorAll('[data-tool]').forEach(b=>b.onclick=()=>setTool(b.dataset.tool));document.querySelectorAll('[data-weather]').forEach(b=>b.onclick=()=>{sim.catalyst(b.dataset.weather);document.querySelectorAll('[data-weather]').forEach(o=>o.classList.toggle('active',o===b));$('temperature').value=sim.temperature;$('temperatureValue').textContent=sim.temperature;save();update()});document.querySelectorAll('[data-event]').forEach(b=>b.onclick=()=>{sim.catalyst(b.dataset.event);save();update();toast('City conditions changed. Watch citizens respond.')});for(const k of ['fertility','power','temperature'])$(k).oninput=()=>{sim[k]=+$(k).value;$(k+'Value').textContent=sim[k]};$('light').onchange=()=>{sim.light=$('light').value;save()};$('undo').onclick=()=>{const result=undoBuild(sim);toast(result.message);save();update()};$('exportWorld').onclick=()=>download('free-city-world-and-minds.json',sim);if(gameState(sim).run?.status==='active'){for(const el of $('drawer').querySelectorAll('[data-weather],[data-event],#fertility,#power,#temperature,[data-tool="hazard"],[data-tool="restore"]')){el.disabled=true;el.title='Challenge conditions are fixed. Return to free play to use this control.'}}}
$('people').onclick=showPeople;$('catalyst').onclick=sandbox;$('help').onclick=()=>$('guide').showModal();$('guideClose').onclick=()=>$('guide').close();$('reset').onclick=()=>{if(confirm('Start a new civilization? Export your world first if you want to keep the current one.')){sim=new Simulation();selected=sim.citizens[0].id;following=false;setTool('');world.scene.userData={};sim.world.revision=Date.now();save();update();$('guide').close()}};
$('district').innerHTML='<option value="">Jump to a neighborhood…</option>'+districts.map((d,i)=>`<option value="${i}">${d}</option>`).join('');$('district').onchange=()=>{if($('district').value==='')return;target.set(-70+Number($('district').value)*20,0,0);distance=105;following=false};
function updateGameHUD(){const g=gameState(sim),r=g.run;$('play').textContent=g.mode==='chaos'?'⚗ Chaos Lab':'☆ City Stories';if($('grantBudget'))$('grantBudget').textContent=remaining(sim);if(!r){$('objectiveHUD').innerHTML=`<span>${g.mode==='chaos'?'CHAOS LAB':'CITY STORIES'}</span><b>${g.mode==='chaos'?'What happens if…?':'A city full of possibilities.'}</b><button id="chooseChallenge">Choose a challenge</button>`;$('chooseChallenge').onclick=openLobby;return}const m=missions.find(m=>m.id===r.id),elapsed=sim.tick-r.started,items=goals(sim);document.querySelectorAll('[data-goal]').forEach(el=>{const i=+el.dataset.goal,o=items[i];if(!o)return;el.classList.toggle('done',o.value>=o.target);el.querySelector('b').textContent=(o.value>=o.target?'✓ ':'○ ')+m.objectives[i];el.querySelector('progress').value=o.value;el.querySelector('small').textContent=Math.min(o.value,o.target)+' / '+o.target});$('objectiveHUD').innerHTML=`<span>${r.status==='active'?'CHALLENGE':r.status==='won'?'COMPLETE':'TRY AGAIN'} · ${m.title}</span><div class="mini-goals">${items.map((o,i)=>`<span title="${m.objectives[i]}">${o.value>=o.target?'✓':'○'} ${Math.min(o.value,o.target)}/${o.target}</span>`).join('')}</div><b>${r.status==='active'?remaining(sim)+' grant coins':r.stars+' / 3 stars'}${m.limit&&r.status==='active'?' · '+Math.max(0,Math.ceil((m.limit-elapsed)*.12))+'s at 1× left':''}</b><button id="goalDetails">View goals</button>`;$('goalDetails').onclick=showGoals;if(r.status!=='active'&&!r.notified){r.notified=true;setSpeed(0);showGoals();save()}}
function showGoals(){const r=gameState(sim).run;if(!r){openLobby();return}const m=missions.find(m=>m.id===r.id),items=goals(sim);openDrawer('goals');$('drawer').innerHTML=`<div class="section-title">${r.status==='won'?'CHALLENGE COMPLETE':r.status==='lost'?'CHALLENGE ENDED':'YOUR CHALLENGE'}<button id="drawerClose">×</button></div><h2>${m.title}</h2>${r.status!=='active'?`<div class="stars">${r.stars?'★'.repeat(r.stars)+'☆'.repeat(3-r.stars):'A new plan, a new chance.'}</div>`:''}<p class="mem">${m.description}</p>${items.map((o,i)=>`<div data-goal="${i}" class="goal-item ${o.value>=o.target?'done':''}"><b>${o.value>=o.target?'✓':'○'} ${m.objectives[i]}</b><progress max="${o.target}" value="${o.value}"></progress><small>${Math.min(o.value,o.target)} / ${o.target}</small></div>`).join('')}<div class="goal-card"><b>FIELD NOTE</b><p>${m.hint}</p></div><p class="mem">Construction grant: ${Math.max(0,r.grant-r.spent)} / ${r.grant}. Your existing city, citizens, and memories are preserved.</p><button id="goBuild" class="wide">${r.status==='active'?'Open building tools':'Keep playing in this city'}</button><button id="leaveChallenge" class="wide">${r.status==='active'?'End challenge · keep my city':'Return to free play'}</button>`;$('drawerClose').onclick=closeDrawer;$('goBuild').onclick=()=>{if(r.status==='active'){drawer='';sandbox();setSpeed(1)}else{freePlay(sim,gameState(sim).mode);closeDrawer();setSpeed(1);save();update()}};$('leaveChallenge').onclick=()=>{if(r.status==='active'&&!confirm('End this challenge? Your city and memories stay; this attempt will not earn a medal.'))return;freePlay(sim,gameState(sim).mode);closeDrawer();setSpeed(1);save();update()}}
function openLobby(){setSpeed(0);setTool('');const g=gameState(sim);$('lobbyBody').innerHTML=`<div class="eyebrow">FREE CITY · CHOOSE HOW TO PLAY</div><h2>Your world. Their lives.</h2><p class="mem">Two ways to play in the same living city. Switching modes keeps your citizens, buildings, and memories.</p><div class="mode-grid"><button data-mode="city" class="mode-card ${g.mode==='city'?'selected':''}"><span>01 · CITY STORIES</span><strong>Build somewhere<br>they can belong.</strong><p>Cozy building, observation, and community challenges. Turn an ordinary neighborhood into a place people love.</p><b>Choose City Stories →</b></button><button data-mode="chaos" class="mode-card chaos ${g.mode==='chaos'?'selected':''}"><span>02 · CHAOS LAB</span><strong>Change everything.<br>See who adapts.</strong><p>Disaster survival and free experiments. Test storms, blackouts, shortages, and closed roads without controlling citizens.</p><b>Choose Chaos Lab →</b></button></div><div class="lobby-section"><h3>${g.mode==='city'?'COMMUNITY CHALLENGES':'SURVIVAL CHALLENGES'}</h3><div class="mission-list">${missions.filter(m=>m.mode===g.mode).map(m=>`<button data-mission="${m.id}" ${g.run?.status==='active'?'disabled':''}><span>${m.tag}</span><b>${m.title}</b><p>${m.description}</p><small>${'★'.repeat(g.medals[m.id]||0)} ${g.medals[m.id]?'Best medal':'Not completed'} · ${m.grant} construction coins</small></button>`).join('')}</div></div><div class="lobby-actions"><button id="continueCity">${g.run?.status==='active'?'View current challenge':'Enter free play'}</button><button id="lobbyGuide">How to play</button><a href="https://github.com/KartBala07/free-city" target="_blank" rel="noopener">Project on GitHub ↗</a></div><p class="brain-note">You control the environment. Citizens choose their own actions. Your city and citizen memories save to your shared username. Anyone knowing that name can access it.</p>`;document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{if(g.run?.status==='active'&&b.dataset.mode!==g.mode&&!confirm('Leave the current challenge and switch modes? Your city and memories will remain.'))return;if(b.dataset.mode!==g.mode)freePlay(sim,b.dataset.mode);g.visited=true;save();openLobby()});document.querySelectorAll('[data-mission]').forEach(b=>b.onclick=()=>{const result=startMission(sim,b.dataset.mission);toast(result.message);if(result.ok){$('lobby').close();showGoals();save();update()}});$('continueCity').onclick=()=>{g.visited=true;$('lobby').close();if(g.run?.status==='active')showGoals();setSpeed(1);save();update()};$('lobbyGuide').onclick=()=>{$('lobby').close();$('guide').showModal()};if(!$('lobby').open)$('lobby').showModal()}
$('playerName').textContent=profile||'Demo';$('logout').onclick=async()=>{setSpeed(0);$('logout').disabled=true;while(saving)await new Promise(r=>setTimeout(r,100));const ok=await save();if(ok||demo||confirm('Cloud save did not finish. Cancel to export a backup, or log out with the last cloud save.')){leaving=true;logOut();}else $('logout').disabled=false;};$('saveNow').onclick=()=>save();$('reloadCloud').onclick=()=>{if(confirm('Reload the latest cloud save? Export your current world first to keep unsynced changes.'))location.reload();};$('exportBackup').onclick=()=>download('free-city-world-and-minds.json',sim);$('play').onclick=openLobby;$('lobbyClose').onclick=()=>{gameState(sim).visited=true;$('lobby').close();setSpeed(1);save()};$('lobby').addEventListener('cancel',()=>{gameState(sim).visited=true;setSpeed(1);save()});
let prior=performance.now(),acc=0,lastUI=0;function frame(now){requestAnimationFrame(frame);const dt=Math.min((now-prior)/1000,.1);prior=now;acc+=dt*speed;let count=0;while(acc>=.12&&count<35){sim.step();challengeStep(sim);acc-=.12;count++}const c=person();if(following&&c&&!c.died)target.lerp(new T.Vector3(c.x,0,c.z),Math.min(1,dt*6));if(keys.has('w')||keys.has('arrowup'))pan(0,dt*220);if(keys.has('s')||keys.has('arrowdown'))pan(0,-dt*220);if(keys.has('a')||keys.has('arrowleft'))pan(dt*220,0);if(keys.has('d')||keys.has('arrowright'))pan(-dt*220,0);if(keys.has('q'))angle-=dt;if(keys.has('e'))angle+=dt;if(auto)angle+=dt*.07;world.camera.position.set(target.x+Math.sin(angle)*Math.cos(elevation)*distance,Math.sin(elevation)*distance,target.z+Math.cos(angle)*Math.cos(elevation)*distance);world.camera.lookAt(target);world.update(sim,selected,speed?dt:0,now);world.renderer.render(world.scene,world.camera);if(now-lastUI>800){update();lastUI=now}}update();requestAnimationFrame(frame);if(!gameState(sim).visited)openLobby();
